CREATE TABLE public.job_risers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,job_id uuid NOT NULL REFERENCES public.jobs(id),asset_id uuid NOT NULL REFERENCES public.assets(id),selected boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(job_id,asset_id));
GRANT SELECT ON public.job_risers TO authenticated; GRANT ALL ON public.job_risers TO service_role;
ALTER TABLE public.job_risers ENABLE ROW LEVEL SECURITY;
CREATE POLICY job_risers_staff_read ON public.job_risers FOR SELECT TO authenticated USING(org_id=public.get_user_org_id() AND (public.has_role_in_org(auth.uid(),org_id,'admin') OR EXISTS(SELECT 1 FROM public.job_assignments ja WHERE ja.job_id=job_risers.job_id AND ja.engineer_id=auth.uid() AND ja.org_id=job_risers.org_id)));
CREATE FUNCTION public.set_job_riser(_job_id uuid,_asset_id uuid,_selected boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o uuid:=public.get_user_org_id(); BEGIN IF o IS NULL OR NOT public.has_role_in_org(auth.uid(),o,'admin') THEN RAISE EXCEPTION 'Office access required'; END IF; IF NOT EXISTS(SELECT 1 FROM jobs j JOIN assets a ON a.site_id=j.site_id AND a.org_id=j.org_id WHERE j.id=_job_id AND j.org_id=o AND j.status<>'archived' AND a.id=_asset_id AND a.merged_into_asset_id IS NULL AND a.status<>'decommissioned' AND a.asset_type IN ('Dry Riser','Wet Riser')) THEN RAISE EXCEPTION 'Riser must belong to this job site and company'; END IF; INSERT INTO job_risers(org_id,job_id,asset_id,selected) VALUES(o,_job_id,_asset_id,_selected) ON CONFLICT(job_id,asset_id) DO UPDATE SET selected=EXCLUDED.selected; INSERT INTO job_activity_log(job_id,user_id,org_id,action,details) VALUES(_job_id,auth.uid(),o,'riser_selection_changed',_asset_id::text||CASE WHEN _selected THEN ' included on visit' ELSE ' excluded from visit' END); END $$;
REVOKE ALL ON FUNCTION public.set_job_riser(uuid,uuid,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.set_job_riser(uuid,uuid,boolean) TO authenticated;
INSERT INTO public.job_risers(org_id,job_id,asset_id) SELECT j.org_id,j.id,a.id FROM public.jobs j JOIN public.assets a ON a.id=j.asset_id AND a.org_id=j.org_id AND a.site_id=j.site_id WHERE a.asset_type IN ('Dry Riser','Wet Riser') ON CONFLICT DO NOTHING;
INSERT INTO public.job_risers(org_id,job_id,asset_id) SELECT DISTINCT j.org_id,j.id,a.id FROM public.jobs j JOIN public.job_sheet_responses r ON r.job_id=j.id JOIN public.assets a ON a.id::text IN (r.responses->>'riser_asset_id',r.responses->'_riser_visit'->>'asset_id') AND a.org_id=j.org_id AND a.site_id=j.site_id WHERE a.asset_type IN ('Dry Riser','Wet Riser') ON CONFLICT DO NOTHING;
CREATE FUNCTION public.initialise_job_risers() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO job_risers(org_id,job_id,asset_id) SELECT NEW.org_id,NEW.id,a.id FROM assets a WHERE a.org_id=NEW.org_id AND a.site_id=NEW.site_id AND a.merged_into_asset_id IS NULL AND a.status<>'decommissioned' AND a.asset_type IN ('Dry Riser','Wet Riser') AND (NEW.asset_id IS NULL OR a.id=NEW.asset_id) AND coalesce(NEW.source,'')<>'Riser visit'; RETURN NEW; END $$;
CREATE TRIGGER initialise_job_risers AFTER INSERT ON public.jobs FOR EACH ROW EXECUTE FUNCTION public.initialise_job_risers();
CREATE FUNCTION public.link_visit_response_riser() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO job_risers(org_id,job_id,asset_id) SELECT j.org_id,j.id,a.id FROM jobs j JOIN assets a ON a.site_id=j.site_id AND a.org_id=j.org_id WHERE j.id=NEW.job_id AND a.id::text IN (NEW.responses->>'riser_asset_id',NEW.responses->'_riser_visit'->>'asset_id') AND a.asset_type IN ('Dry Riser','Wet Riser') ON CONFLICT DO NOTHING; RETURN NEW; END $$;
CREATE TRIGGER link_visit_response_riser AFTER INSERT OR UPDATE OF responses ON public.job_sheet_responses FOR EACH ROW EXECUTE FUNCTION public.link_visit_response_riser();